def isLucky(s):
    s = str(s)
    for i in range(len(s)):
        if s[i] != "4" and s[i] != "7":
            return False
        else:
            return True
def lucky2(l):
    for i in l:
        if i!=4 and i!=7:
            return False
        else:
            return True
def Turnlist(n):
    n=list(n)
    for i in range(len(n)):
        n[i]=int(n[i])
    return n


